package io.github.rhythmache.spake2.internal

/**
 * SPAKE2 mask points M and N as used by boringSSL's edwards25519 SPAKE2.
 * these are NUMSstyle points generated by hashing fixed seed strings and
 * decoding the result as a curve point. values taken directly from
 * curve25519.c (kSpakeMSmallPrecomp / kSpakeNSmallPrecomp headers).
 *
 * Role assignment (see pairing_auth.cpp / spake2_role_t):>
 *   :> Alice masks her own message with M, and uses N to unmask Bob's.
 *   :> Bob masks his own message with N, and uses M to unmask Alice's.
 */
internal object Spake2Constants {
    // Base point B (Ed25519 standard generator point)
    val B_ENCODED: ByteArray =
        hexToBytes(
            "5866666666666666666666666666666666666666666666666666666666666666",
        )

    // N (used by Bob to mask his own point; Alice uses N to unmask Bob's)
    val N_ENCODED: ByteArray =
        hexToBytes(
            "10e3df0ae37d8e7a99b5fe74b44672103dbddcbd06af680d71329a11693bc778",
        )

    // M (used by Alice to mask her own point; Bob uses M to unmask Alice's)
    val M_ENCODED: ByteArray =
        hexToBytes(
            "5ada7e4bf6ddd9adb6626d32131c6b5c51a1e347a3478f53cfcf441b88eed12e",
        )

    private fun hexToBytes(hex: String): ByteArray {
        val clean = hex.trim()
        val out = ByteArray(clean.length / 2)
        for (i in out.indices) {
            out[i] = clean.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
        return out
    }
}
